import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as i,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Origin","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/cursor/origin.md","filePath":"products/ai-coding/cursor/origin.md","lastUpdated":1787046041000}'),a={name:"products/ai-coding/cursor/origin.md"};function o(n,s,l,h,p,c){return i(),e("div",null,[...s[0]||(s[0]=[r(`<h1 id="origin" tabindex="-1">Origin <a class="header-anchor" href="#origin" aria-label="Permalink to &quot;Origin&quot;">​</a></h1><p>Origin is <strong>Cursor&#39;s git forge</strong> (early beta): host repos, mirror GitHub, browse and search at <a href="https://cursor.com/codebase" target="_blank" rel="noreferrer">cursor.com/codebase</a>, and open or merge pull requests. It is a <strong>hosted-code product</strong>, not another Rules file.</p><blockquote><p>Official: <a href="https://cursor.com/docs/origin" target="_blank" rel="noreferrer">Origin</a>. Feedback: <a href="mailto:hi@cursor.com" target="_blank" rel="noreferrer">hi@cursor.com</a>.</p><p>The Origin CLI binary is <strong><code>origin</code></strong>. That is not the Cursor Agent CLI binary <strong><code>agent</code></strong>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A <strong>Pro, Teams, or Enterprise</strong> plan. Origin code storage is <strong>not</strong> on free plans</li><li>Access rolls out in stages — you may not see Origin the day it lands on your plan</li><li>Teams on <strong>legacy privacy mode cannot enable Origin</strong>. Switch to <a href="https://cursor.com/help/security-and-privacy/privacy.md#how-do-i-enable-privacy-mode" target="_blank" rel="noreferrer">Privacy Mode</a> first</li><li>You can use git, and you know GitHub is optional here (mirror when the source already lives there)</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>After this page you can:</p><ol><li>Tell Origin apart from Rules, Bugbot, and “just another GitHub integration”</li><li>Claim a <strong>codebase name</strong> and create or mirror a repo</li><li>Clone / push with standard git or the Origin CLI</li><li>Know what a GitHub mirror copies — and what it does <strong>not</strong></li></ol><hr><h2 id="what-origin-is-and-is-not" tabindex="-1">What Origin is (and is not) <a class="header-anchor" href="#what-origin-is-and-is-not" aria-label="Permalink to &quot;What Origin is (and is not)&quot;">​</a></h2><p>Official early-beta list: create repos (including from Cursor agents), clone / push / pull with standard git, <a href="https://cursor.com/docs/origin/mirror-github" target="_blank" rel="noreferrer">mirror a GitHub repository</a>, <a href="https://cursor.com/docs/origin/pull-requests" target="_blank" rel="noreferrer">open / review / merge PRs</a>, <a href="https://cursor.com/docs/origin/browse" target="_blank" rel="noreferrer">browse and search</a> at <code>cursor.com/codebase/{owner}/{repo}</code>, manage repo and codebase settings, connect third-party apps (Vercel, Depot, Buildkite), connect <a href="https://cursor.com/docs/origin/integrations" target="_blank" rel="noreferrer">automations and cloud agents</a>, and install the <a href="https://cursor.com/docs/origin/cli" target="_blank" rel="noreferrer">Origin CLI</a>.</p><table tabindex="0"><thead><tr><th>This</th><th>Not this</th></tr></thead><tbody><tr><td>Git host + browser for your team&#39;s code</td><td>A replacement for <code>.cursor/rules</code></td></tr><tr><td>Namespace <code>{owner}</code> in <code>https://cursor.com/codebase/{owner}/{repo}</code></td><td>A Bugbot check on a GitHub PR</td></tr><tr><td>Optional GitHub <strong>mirror</strong></td><td>Automatic copy of GitHub Issues or Actions</td></tr></tbody></table><p>Closest cousins on this site: Cloud Agents can clone, branch, commit, push, and open PRs <strong>on Origin remotes</strong>. Bugbot / Cursor Review comment on GitHub PRs <strong>without moving storage</strong>.</p><h2 id="who-can-access" tabindex="-1">Who can access <a class="header-anchor" href="#who-can-access" aria-label="Permalink to &quot;Who can access&quot;">​</a></h2><p>Origin code storage is available on <strong>Pro, Teams, and Enterprise</strong>. It is <strong>not</strong> available on free plans.</p><p><strong>Privacy:</strong> Origin follows the <a href="https://cursor.com/help/security-and-privacy/privacy.md" target="_blank" rel="noreferrer">Privacy Mode</a> of the <strong>namespace owner</strong> — the team or the individual who owns the repo.</p><h2 id="enable-origin" tabindex="-1">Enable Origin <a class="header-anchor" href="#enable-origin" aria-label="Permalink to &quot;Enable Origin&quot;">​</a></h2><p>Someone has to <strong>claim a codebase name</strong> first. That name is the <code>{owner}</code> in <code>https://cursor.com/codebase/{owner}/{repo}</code>.</p><ol><li>Open <a href="https://cursor.com/codebase" target="_blank" rel="noreferrer">cursor.com/codebase</a></li><li>Select <strong>Get Started</strong> and finish setup</li><li>Any team member can claim the name</li><li>Admins can disable Origin for the team from the dashboard at any time</li><li>After the name is claimed, admins create repositories and grant access from <a href="https://cursor.com/docs/origin/codebase-settings.md#permissions" target="_blank" rel="noreferrer">codebase settings</a></li></ol><p>The repo list then shows <strong>Find repo...</strong>, <strong>New</strong>, and <strong>Sync from GitHub</strong>. Icons tell Origin-hosted repos from GitHub-synced ones.</p><h2 id="create-a-repository" tabindex="-1">Create a repository <a class="header-anchor" href="#create-a-repository" aria-label="Permalink to &quot;Create a repository&quot;">​</a></h2><p>Official: <a href="https://cursor.com/docs/origin/create-repository" target="_blank" rel="noreferrer">Create a repository</a>.</p><p>From <a href="https://cursor.com/codebase" target="_blank" rel="noreferrer">cursor.com/codebase</a>:</p><ol><li>Select <strong>New</strong></li><li>Enter a <strong>Repo Name</strong></li><li>Choose visibility: <strong>Internal</strong> (anyone with access to the team&#39;s codebase) or <strong>Private</strong> (only members granted access)</li><li>Select <strong>Create Repo</strong></li><li>Copy the clone URL from the green <strong>Code</strong> button</li></ol><p>If the code already lives on GitHub, use <strong>Sync from GitHub</strong> instead of <strong>New</strong>.</p><p>Cursor agents can create Origin repos as part of a task. They use the same permissions as your Cursor account. Cloud agents work against <strong>existing</strong> Origin repositories: clone, branch, commit, push, and open PRs.</p><p>Empty repo, then first push:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://origin.cursor.com/{owner}/{repo}.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {repo}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># add your files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Initial commit&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><p>Existing local project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://origin.cursor.com/{owner}/{repo}.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><h2 id="clone-push-and-pull" tabindex="-1">Clone, push, and pull <a class="header-anchor" href="#clone-push-and-pull" aria-label="Permalink to &quot;Clone, push, and pull&quot;">​</a></h2><p>Official: <a href="https://cursor.com/docs/origin/git" target="_blank" rel="noreferrer">Clone, Push &amp; Pull</a>. HTTPS remote:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://origin.cursor.com/{owner}/{repo}.git</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://origin.cursor.com/acme/checkout.git</span></span></code></pre></div><p>Sign in with the Origin CLI before the first git operation if you have not already:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://downloads.cursor.com/origin/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>The installer puts the binary at <code>~/.local/bin/origin</code>. If the shell says <code>command not found: origin</code>, add that directory to <code>PATH</code>. Login also sets up the git credential helper.</p><p>Keep GitHub and Origin in parallel while you evaluate:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-url</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:acme/checkout.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-url</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://origin.cursor.com/acme/checkout.git</span></span></code></pre></div><p>For a full history copy, prefer <strong>mirroring</strong>.</p><h2 id="mirror-a-github-repository" tabindex="-1">Mirror a GitHub repository <a class="header-anchor" href="#mirror-a-github-repository" aria-label="Permalink to &quot;Mirror a GitHub repository&quot;">​</a></h2><p>Official: <a href="https://cursor.com/docs/origin/mirror-github" target="_blank" rel="noreferrer">Mirror a GitHub repository</a>.</p><p><strong>Prerequisites:</strong> Origin access on Pro / Teams / Enterprise; the <a href="https://cursor.com/docs/integrations/github" target="_blank" rel="noreferrer">Cursor GitHub app</a> connected; <strong>GitHub admin</strong> on the source repo.</p><ol><li>Open <a href="https://cursor.com/codebase" target="_blank" rel="noreferrer">cursor.com/codebase</a></li><li>Select <strong>Sync from GitHub</strong></li><li>Choose the GitHub organization and repository</li><li>Confirm the sync</li></ol><table tabindex="0"><thead><tr><th>Included</th><th>Not included</th></tr></thead><tbody><tr><td>Git history, branches, and tags</td><td>GitHub Issues</td></tr><tr><td>Code you can browse and search on Origin</td><td>GitHub Actions workflows and secrets</td></tr><tr><td>Pull requests, which sync in <strong>both</strong> directions</td><td></td></tr><tr><td>Ongoing updates so Origin stays fresh</td><td></td></tr></tbody></table><p>On a mirrored repo, Origin is the mirror and GitHub remains the <strong>source of truth</strong>. Pushes to the Origin remote pass through to GitHub. PRs opened on Origin sync back to GitHub.</p><p><strong>Detach from GitHub</strong> (Settings → General → Danger Zone) stops the sync and makes Origin the source of truth. Your GitHub repository is not affected.</p><p>If you only want review comments on GitHub PRs, use <a href="https://cursor.com/docs/cursor-review/overview" target="_blank" rel="noreferrer">Cursor Review</a> or <a href="https://cursor.com/docs/bugbot" target="_blank" rel="noreferrer">Bugbot</a> without moving storage.</p><h2 id="pull-requests" tabindex="-1">Pull requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to &quot;Pull requests&quot;">​</a></h2><p>Official: <a href="https://cursor.com/docs/origin/pull-requests" target="_blank" rel="noreferrer">Pull requests</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-change</span></span></code></pre></div><p>Then use the create-pull-request flow on the <strong>Code</strong> tab. Cloud agents can open Origin PRs as part of a task.</p><p>Each PR has four tabs: <strong>Activity</strong>, <strong>Commits</strong>, <strong>Checks</strong>, <strong>Files Changed</strong>. You can request reviewers, comment on lines, and merge once reviews and CI are satisfied.</p><p>PRs on a repo <strong>created directly on Origin stay on Origin</strong>. They are not mirrored anywhere.</p><h2 id="origin-cli-vs-cursor-cli" tabindex="-1">Origin CLI vs Cursor CLI <a class="header-anchor" href="#origin-cli-vs-cursor-cli" aria-label="Permalink to &quot;Origin CLI vs Cursor CLI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Binary</th><th>Install</th><th>Job</th></tr></thead><tbody><tr><td><strong><code>origin</code></strong></td><td><code>curl -fsSL https://downloads.cursor.com/origin/install.sh | sh</code></td><td>Auth, create / delete repos, git helper</td></tr><tr><td><strong><code>agent</code></strong></td><td><code>curl https://cursor.com/install -fsS | bash</code></td><td>Cursor coding agent in a terminal</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme/my-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p><code>origin repo create</code> without a slash creates the repo in your account&#39;s namespace. <code>origin repo delete</code> always takes the full <code>org/name</code>. Command reference: <a href="https://cursor.com/docs/origin/cli/reference/commands" target="_blank" rel="noreferrer">Origin CLI commands</a>.</p><h2 id="when-to-use-origin" tabindex="-1">When to use Origin <a class="header-anchor" href="#when-to-use-origin" aria-label="Permalink to &quot;When to use Origin&quot;">​</a></h2><ul><li>You want Cursor-hosted storage, browse, search, and PRs — not just a GitHub comment bot</li><li>A Cloud Agent or Automation should work against an Origin remote</li><li>You are evaluating a GitHub mirror so agents can use Origin browse + PR sync</li></ul><p>Stay on GitHub-only when policy forbids a second host, or when you only need Bugbot comments.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Do this</th></tr></thead><tbody><tr><td>Treat Origin as “more Rules”</td><td>It stores <strong>code</strong>. Rules stay in <code>.cursor/rules</code> / <code>AGENTS.md</code></td></tr><tr><td>Expect it on the free plan</td><td>Pro / Teams / Enterprise only</td></tr><tr><td>Enable on <strong>legacy</strong> privacy</td><td>Switch to Privacy Mode first</td></tr><tr><td>Type <code>agent</code> when you meant the forge CLI</td><td>Install <strong><code>origin</code></strong></td></tr><tr><td>Mirror to get GitHub Issues / Actions</td><td>Those stay on GitHub</td></tr><tr><td>Detach and still expect GitHub to receive Origin pushes</td><td>After detach, Origin is the source of truth</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./cloud-agents.html">Cloud Agents</a> — agents can work on Origin remotes</li><li><a href="./cursor-cli.html">Cursor CLI</a> — coding agent binary <code>agent</code>, not <code>origin</code></li><li><a href="./security-agents.html">Security Agents</a> and <a href="./pr-routing.html">PR Routing</a> — review / route <strong>after</strong> the code is hosted</li><li>Official: <a href="https://cursor.com/docs/origin" target="_blank" rel="noreferrer">Origin</a>, <a href="https://cursor.com/docs/origin/create-repository" target="_blank" rel="noreferrer">Create</a>, <a href="https://cursor.com/docs/origin/mirror-github" target="_blank" rel="noreferrer">Mirror</a>, <a href="https://cursor.com/docs/origin/integrations" target="_blank" rel="noreferrer">Integrations</a></li></ul>`,65)])])}const m=t(a,[["render",o]]);export{b as __pageData,m as default};
